using KooliProjekt.Application.Behaviors;
using KooliProjekt.Application.Infrastructure.Results;
using MediatR;

namespace KooliProjekt.Application.Features.FoodEntrys
{
    public class DeleteFoodEntrysCommand : IRequest<OperationResult>, ITransactional
    {
        public int Id { get; set; }
    }
}

using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using KooliProjekt.Application.Data;
using KooliProjekt.Application.Infrastructure.Results;
using MediatR;
using Microsoft.EntityFrameworkCore;

namespace KooliProjekt.Application.Features.FoodEntrys
{
    public class DeleteFoodEntrysCommandHandler : IRequestHandler<DeleteFoodEntrysCommand, OperationResult>
    {
        private readonly ApplicationDbContext _dbContext;

        public DeleteFoodEntrysCommandHandler(ApplicationDbContext dbContext)
        {
            _dbContext = dbContext;
        }

        public async Task<OperationResult> Handle(DeleteFoodEntrysCommand request, CancellationToken cancellationToken)
        {
            var result = new OperationResult();

            await _dbContext
                .FoodEntries
                .Where(t => t.Id == request.Id)
                .ExecuteDeleteAsync();

            return result;
        }
    }
}

using KooliProjekt.Application.Data;
using KooliProjekt.Application.Infrastructure.Results;
using MediatR;

namespace KooliProjekt.Application.Features.FoodEntrys
{
    public class GetFoodEntrysQuery : IRequest<OperationResult<object>>
    {
        public int Id { get; set; }
    }
}

using System.Threading;
using System.Threading.Tasks;
using KooliProjekt.Application.Data;
using KooliProjekt.Application.Infrastructure.Results;
using MediatR;
using Microsoft.EntityFrameworkCore;

namespace KooliProjekt.Application.Features.FoodEntrys
{
    public class GetFoodEntrysQueryHandler : IRequestHandler<GetFoodEntrysQuery, OperationResult<object>>
    {
        private readonly ApplicationDbContext _dbContext;

        public GetFoodEntrysQueryHandler(ApplicationDbContext dbContext)
        {
            _dbContext = dbContext;
        }

        public async Task<OperationResult<object>> Handle(GetFoodEntrysQuery request, CancellationToken cancellationToken)
        {
            var result = new OperationResult<object>();
            var foodEntry = await _dbContext.FoodEntries.FirstOrDefaultAsync(f => f.Id == request.Id, cancellationToken);

            result.Value = new
            {
                Id = foodEntry.Id,
                FoodItemId = foodEntry.FoodItemId,
                Quantity = foodEntry.Quantity,
                EntryDate = foodEntry.EntryDate
            };

            return result;
        }
    }
}

using KooliProjekt.Application.Behaviors;
using KooliProjekt.Application.Infrastructure.Results;
using MediatR;
using System;

namespace KooliProjekt.Application.Features.FoodEntrys
{
    public class SaveFoodEntrysCommand : IRequest<OperationResult>, ITransactional
    {
        public int Id { get; set; }
        public int FoodItemId { get; set; }
        public int Quantity { get; set; }
        public DateTime EntryDate { get; set; }
    }
}

using System.Threading;
using System.Threading.Tasks;
using KooliProjekt.Application.Data;
using KooliProjekt.Application.Infrastructure.Results;
using MediatR;

namespace KooliProjekt.Application.Features.FoodEntrys
{
    public class SaveFoodEntrysCommandHandler : IRequestHandler<SaveFoodEntrysCommand, OperationResult>
    {
        private readonly ApplicationDbContext _dbContext;

        public SaveFoodEntrysCommandHandler(ApplicationDbContext dbContext)
        {
            _dbContext = dbContext;
        }

        public async Task<OperationResult> Handle(SaveFoodEntrysCommand request, CancellationToken cancellationToken)
        {
            var result = new OperationResult();

            var foodEntry = new FoodEntry();
            if (request.Id != 0)
            {
                foodEntry = await _dbContext.FoodEntries.FindAsync(new object[] { request.Id }, cancellationToken: cancellationToken);
            }

            foodEntry.FoodItemId = request.FoodItemId;
            foodEntry.Quantity = request.Quantity;
            foodEntry.EntryDate = request.EntryDate;

            if (request.Id == 0)
            {
                _dbContext.FoodEntries.Add(foodEntry);
            }

            await _dbContext.SaveChangesAsync(cancellationToken);

            return result;
        }
    }
}

using FluentValidation;
using KooliProjekt.Application.Data;

namespace KooliProjekt.Application.Features.FoodEntrys
{
    public class SaveFoodEntrysCommandValidator : AbstractValidator<SaveFoodEntrysCommand>
    {
        public SaveFoodEntrysCommandValidator(ApplicationDbContext context)
        {
            RuleFor(x => x.FoodItemId)
                .GreaterThan(0).WithMessage("FoodItemId is required");

            RuleFor(x => x.Quantity)
                .GreaterThan(0).WithMessage("Quantity must be greater than 0");

            RuleFor(x => x.EntryDate)
                .NotEmpty().WithMessage("EntryDate is required");
        }
    }
}
